using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
public sealed class ForgeCodeView:MonoBehaviour,IPointerDownHandler
{
 public InputField title;public ForgeCodeInput editor;public Button run,step,stop,collapse,close;public Text status;public RectTransform body;public RectTransform editorArea,statusArea;public RectTransform rect;ForgeMvp game;int id;bool syncing;Rect last;Image header;Color headerColor;ForgeUIHover errorHover;ForgeExecutionLine executionHighlight;
 public void Bind(ForgeMvp owner,int key){game=owner;id=key;ForgeSfxButton.Bind(this);executionHighlight=editor.gameObject.GetComponent<ForgeExecutionLine>()??editor.gameObject.AddComponent<ForgeExecutionLine>();executionHighlight.Initialize(editor);header=transform.Find("CodeHeader").GetComponent<Image>();headerColor=header.color;errorHover=header.GetComponent<ForgeUIHover>();if(!errorHover)errorHover=header.gameObject.AddComponent<ForgeUIHover>();errorHover.Bind(owner.HierarchyGame);var resizeHint=transform.Find("ResizeCode").GetComponent<ForgeUIHover>();if(resizeHint)resizeHint.Bind(owner.HierarchyGame);ForgeCodeColors.Apply(editor.textComponent);editor.GetComponent<ForgeCodeHelp>().Bind(owner.HierarchyGame);status.GetComponent<Button>().onClick.AddListener(()=>game.GameCodeAction(id,"reveal"));run.onClick.AddListener(()=>game.GameCodeAction(id,"run"));step.onClick.AddListener(()=>game.GameCodeAction(id,"step"));stop.onClick.AddListener(()=>game.GameCodeAction(id,"stop"));collapse.onClick.AddListener(()=>game.GameCodeAction(id,"collapse"));close.onClick.AddListener(()=>game.GameCodeAction(id,"close"));editor.onValueChanged.AddListener(value=>{if(!syncing)game.GameCodeEdit(id,value);});title.onEndEdit.AddListener(value=>{if(!syncing&&game)game.GameCodeName(id,value);});}
 public void OnPointerDown(PointerEventData e){game.GameCodeAction(id,"select");rect.SetAsLastSibling();}
 public void Sync(string name,string source,Rect bounds,bool collapsed,bool running,bool canRun,int line,string diagnostic){syncing=true;if(!title.isFocused)title.SetTextWithoutNotify(name);if(editor.text!=source)editor.SetTextWithoutNotify(source);if(bounds!=last){rect.anchoredPosition=new Vector2(bounds.x,-bounds.y);rect.sizeDelta=bounds.size;last=bounds;}body.gameObject.SetActive(!collapsed);if(statusArea){statusArea.gameObject.SetActive(false);editorArea.offsetMin=new Vector2(editorArea.offsetMin.x,0);}run.interactable=step.interactable=canRun;stop.interactable=running||diagnostic!=null;status.text="";if(executionHighlight)executionHighlight.Line=diagnostic==null?line:0;if(header)header.color=diagnostic!=null?new Color(.65f,.12f,.14f,.97f):headerColor;if(errorHover)errorHover.description=diagnostic??"";syncing=false;}
 public void Reveal(int index){StartCoroutine(RevealCaret(index));}
 System.Collections.IEnumerator RevealCaret(int index){editor.ActivateInputField();yield return null;editor.caretPosition=Mathf.Clamp(index,0,editor.text.Length);editor.ForceLabelUpdate();}
 void LateUpdate(){CommitBounds();if(game&&executionHighlight){game.GameWorkerLines(id,executionHighlight.WorkerLines);game.CoolingBreakpointLines(id,executionHighlight.BreakpointLines);} }
 void OnDisable(){CommitBounds();}
 public void Detach(){syncing=true;game=null;}
 public void CommitBounds(){if(game==null)return;var bounds=new Rect(rect.anchoredPosition.x,-rect.anchoredPosition.y,rect.sizeDelta.x,rect.sizeDelta.y);if(bounds!=last){last=bounds;game.GameCodeBounds(id,bounds);}}
}
